        function indexArrayWithSmartDateSuffix($array) {
        // นับจำนวนรายการต่อวันที่
        $dateOccurrences = [];
        foreach ($array as $row) {
            $date = $row['Product_date'];
            if (!isset($dateOccurrences[$date])) {
                $dateOccurrences[$date] = 0;
            }
            $dateOccurrences[$date]++;
        }

        // สร้างรายการใหม่พร้อม suffix เฉพาะวันที่ซ้ำ
        $dateCounter = [];
        $result = [];
        foreach ($array as $row) {
            $date = $row['Product_date'];

            if (!isset($dateCounter[$date])) {
                $dateCounter[$date] = 1;
            } else {
                $dateCounter[$date]++;
            }

            // ถ้าวันนี้มีมากกว่า 1 รายการ ให้เติม suffix
            $row['Product_date'] = ($dateOccurrences[$date] > 1)
                ? $date . '_' . $dateCounter[$date]
                : $date;

            $result[] = $row;
        }

        return $result;
    }
