                        $array1 = $this->indexArrayWithSmartDateSuffix($array1);
                        $array2 = $this->indexArrayWithSmartDateSuffix($array2);

                        // รวมข้อมูลตามวันที่
                        $indexedArray = [];

                        foreach ($array1 as $row) {
                            $indexedArray[$row['Product_date']] = $row;
                        }

                        foreach ($array2 as $row2) {
                            $date = $row2['Product_date'];
                            if (isset($indexedArray[$date])) {
                                $indexedArray[$date]['Average_DN'] = $row2['Average_DN'];
                                $indexedArray[$date]['Upper_control_limit_DN'] = $row2['Upper_control_limit_DN'];
                                $indexedArray[$date]['CL_DN'] = $row2['CL_DN'];
                                $indexedArray[$date]['Trigger_limit_DN'] = $row2['Trigger_limit_DN'];
                            } else {
                                $indexedArray[$date] = $row2;
                            }
                        }

                        // จัดเรียงตามวันที่จริง + ลำดับ suffix ถ้ามี
                        uksort($indexedArray, function($a, $b) {
                            $partsA = explode('_', $a);
                            $partsB = explode('_', $b);

                            $timeA = strtotime($partsA[0]);
                            $timeB = strtotime($partsB[0]);

                            if ($timeA == $timeB) {
                                return ((int)($partsA[1] ?? 0)) - ((int)($partsB[1] ?? 0));
                            }

                            return $timeA - $timeB;
                        });

                        $title =  array (
                            "Product date",
                            "Average (Up)",
                            "Upper control limit_UP",
                            "CL_UP",
                            "Trigger limit_UP",
                            "Average (DN)",
                            "Upper control limit_DN",
                            "CL_DN",
                            "Trigger limit_DN",
                        );
                        
                        $worksheet->fromArray($title, null, "AS31", true);

                        // แปลงกลับเป็น array ปกติ
                        $mergedArray = array_values($indexedArray);
                        $worksheet->fromArray($mergedArray, null, "AS32", true);

                        $lastline = (32+count($mergedArray))-1;

                        $dataSeriesLabels = [
                            new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AT$31', null, 31),
                        ];
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AU$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AV$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AW$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AX$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AY$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AZ$31', null, 31));
                        array_push($dataSeriesLabels, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$BA$31', null, 31));

                        $xAxisTickValues = [
                            new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING, 'FTIR!$AS$32:$AS$'.$lastline, null, 4),
                        ];
                        $dataSeriesValues = [
                            new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AT$32:$AT$'.$lastline ,null , $lastline),
                        ];
                        array_push($dataSeriesValues,new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AU$32:$AU$'.$lastline, null, $lastline)); 
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AV$32:$AV$'.$lastline, null, $lastline));
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AW$32:$AW$'.$lastline, null, $lastline));
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AX$32:$AX$'.$lastline, null, $lastline));
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AY$32:$AY$'.$lastline, null, $lastline));
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$AZ$32:$AZ$'.$lastline, null, $lastline));
                        array_push($dataSeriesValues, new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER, 'FTIR!$BA$32:$BA$'.$lastline, null, $lastline));

                        $series = new DataSeries(
                            DataSeries::TYPE_LINECHART, // ประเภทของแผนภูมิ
                            DataSeries::GROUPING_STANDARD, // การจัดกลุ่มข้อมูล 
                            range(0, count($dataSeriesValues) - 1), // ลำดับข้อมูล เรียงจาก array 0 - 2
                            $dataSeriesLabels, // ชื่อกำกับชุดข้อมูล 
                            $xAxisTickValues, // ข้อความสำหรับแกน x
                            $dataSeriesValues        // ค่าข้อมูล
                        );
                        $layout1 = new Layout();
                        $layout1->setShowVal(true);
                        $layout1->setShowPercent(true);
                        $plotArea = new PlotArea(null, [$series]);
                        $legend = new Legend(Legend::POSITION_BOTTOM, null, false);
                        $title = new Title('Ovey Graph '.$chktext1);
                        $yAxisLabel = new Title('Particle/cm2');
                        $yaxis = new Axis();
                        $xaxis = new Axis();
                        // $yaxis->setAxisOptionsProperties('low', null, null, null, null, null, null, null);
                        // $xaxis->setAxisOptionsProperties('low', null, null, null, null, null, 0, 0, null, null);
                        $grid = new GridLines();
                        $grid->setLineColorProperties("white");
                        $chart0 = new Chart(
                            'chart1',
                            $title,
                            $legend, 
                            $plotArea,
                            true,
                            'gap',
                            null,
                            $yAxisLabel,
                            $yaxis,
                            $xaxis,
                            $grid  // ข้อความอธิบายกำกับแกน Y
                        );
                        $chart0->setTopLeftPosition('AM3');
                        $chart0->setBottomRightPosition('BC28');
                        $spreadsheet->setActiveSheetIndex($iindex)->addChart($chart0);

                    }
                    
                }
               
            $fileType='Xlsx';
            $spacename = str_replace(' ', '', $chktext1);
            $namefile = 'Graph_Customer_'.$spacename.'_'.date("YmdHis").'.xlsx';
            $writer = IOFactory::createWriter($spreadsheet, $fileType);
            $writer->setIncludeCharts(true); 
            ob_end_clean();
            $writer->save('local/storage/NHK-File/report/graphexport/'.$namefile);
            return response()->json(['success' => 1 ,'filename' => $namefile]);
        }          

