        public function getWW_filesem($id_createlab)
        {
            $getfile = DB::table('nt_oqa_file')->where('id_createlab', $id_createlab)->first();
            $getfilename = storage_path('app/public/OQA/SEM/'.$getfile->file_sem);

            Excel::load($getfilename, function($doc)use($id_createlab) {
                $sheet = $doc->setActiveSheetIndex(2);
                $ww = $sheet->getCell('C3')->getCalculatedValue();
                $oqasem = [
                    'wwdate' => $ww,
                ];
                DB::table('nt_data_sem')->where('id_createlab', $id_createlab)->update($oqasem);
            });
        }

        public function excelelementsem(Request $request)
        {

            set_time_limit(1000);
  
            if(isset($request->id))
            {
                if(count($request->id) == 1 )
                {

                    $countline = 0;
                    $namegraph = "ElementSEM";

                    $id = $request->id[0]; 
                    // $datestart = $request->input("datestart".$id);
                    $dateend = $request->input("dateend".$id);
 

                    $a1 = DB::table('nt_model')->where('id_model', $id)->first();
                    $text1 = $a1->name_model;
                    $chktext1 = mb_substr($text1,0,-3);

                    $file = storage_path('NHK-File/template/report/SEMElement_template.xlsx');
                    $filetime = date('YmdHis');
                    $spacename = str_replace(' ', '', $chktext1);
                    $spacename = $spacename.'_'.$a1->part;
                    $namefile = 'SEM_Element_Raw_'.$spacename.'_'.date("YmdHis");
                    $namegraph .= $spacename;

                    $a1 = DB::table('nt_model')->where('id_model', $id)->first();
        
                    $text1 = $a1->name_model;
                    $chktext1 = mb_substr($text1,0,-3);

                    $model1 = $a1;
                    $dateend1 = date('Y-m-d 00:00:00', strtotime($request->input('dateend'.$model1->id_model). ' + 1 day'));
                    
                    $datalsem = DB::table('nt_data_sem')
                    ->join('nt_oqa_lab','nt_oqa_lab.id_createlab','=','nt_data_sem.id_createlab')
                    ->join('nt_oqa_file','nt_oqa_lab.id_createlab','=','nt_oqa_file.id_createlab')
                    ->where('nt_oqa_lab.save_date','>=',$request->input('datestart'.$model1->id_model))
                    ->where('nt_oqa_lab.save_date','<=',$dateend1)
                    ->where('nt_oqa_lab.id_model',$model1->id_model)
                    ->where('nt_oqa_lab.sem_confirm_st',1)
                    ->orderBy('nt_oqa_lab.save_date', 'asc')->get();

                    Excel::load($file, function($doc)use($datalsem,$spacename,$a1) {
                        $sheet = $doc->setActiveSheetIndex(0);
                        $sheet->setCellValue('B2', $spacename);
                        $sheet->setCellValue('B3', $a1->part_number);

                        $i = 'C';
                        $row = 9;
                        $ww = "";

                        //----- fix date start -------
                        $datestart = date('Y-m-d 00:00:00', strtotime('2022-07-23'));

                        foreach ($datalsem as $value) {
                            
                            if($value->sem_datesave > $datestart){
                                $this->getWW_filesem($value->id_createlab);

                                $getlastsem = DB::table('nt_data_sem')->where('id_createlab', $value->id_createlab)->first();

                                $sheet->setCellValue($i.'9', $getlastsem->wwdate );
                                $sheet->setCellValue($i.'25', $getlastsem->wwdate );

                                $sheet->setCellValue($i.'26', $value->I21 );
                                $sheet->setCellValue($i.'27', $value->I22 );
                                $sheet->setCellValue($i.'28', $value->I23 );
                                $sheet->setCellValue($i.'29', $value->I24 );
                                $sheet->setCellValue($i.'30', $value->I25 );
                                $sheet->setCellValue($i.'31', $value->I26 );
                                $sheet->setCellValue($i.'32', $value->I27 );
