        public function customer_elementsem(Request $request)
        {
            set_time_limit(1000);

            if(isset($request->id))
            {
                if(count($request->id) == 1 )
                {

                    $countline = 0;
                    $namegraph = "ElementSEM";

                    $id = $request->id[0]; 
                    $datestart = $request->input("datestart".$id);
                    $dateend = $request->input("dateend".$id);

                    $a1 = DB::table('nt_model')->where('id_model', $id)->first();
                    $text1 = $a1->name_model;
                    $chktext1 = mb_substr($text1,0,-3);

                    $file = storage_path('NHK-File/template/report/SEMElement_template.xlsx');
                    $filetime = date('YmdHis');
                    $spacename = str_replace(' ', '', $chktext1);
                    $spacename = $spacename.'_'.$a1->part;
                    $namefile = 'SEM_Element_customer_'.$spacename.'_'.date("YmdHis");

