        public function dailycheck_export(Request $request)
        {

            if(!empty($request->start_date) && !empty($request->end_date))
            {
                $datestart = date('Y-m-d 00:00:00', strtotime($request->start_date));
                $dateend = date('Y-m-d 23:59:00', strtotime($request->end_date));

                $info = DB::table('nt_dailycheck_info')
                ->whereBetween('due_date', [$datestart, $dateend])
                ->orderby('due_date','ASC')
                ->get();  

            }else{  

                $datestart = date('Y-m-1');
                $dateend = date('Y-m-t');

                $info = DB::table('nt_dailycheck_info')
                ->whereBetween('due_date', [$datestart, $dateend])
                ->orderby('due_date','ASC')
                ->get();  
            }

            $namefile = "excel_dailycheck_".date('YmdHis');
            $file = storage_path('NHK-File/template/report/template_dailycheck.xlsx');

            Excel::load($file, function($doc)use($info) {

                $sheet = $doc->setActiveSheetIndex(0);

                $row = 2;
                foreach ($info as $key => $value) {

                    $arrproblem = [];
                    $arrrootcause = [];
                    $arraction = [];

                    $set = DB::table('nt_dailycheck_set')
                    ->join('nt_dailycheck_unit','nt_dailycheck_unit.id_dyunit','=','nt_dailycheck_set.id_dyunit')
                    ->where('nt_dailycheck_set.id_daily', $value->id_daily)
                    ->first();

                    // Check problem Column
                    if(strlen($value->problem)){
                        $arrproblem[] = $value->problem;
                    }
                    if(strlen($value->problem_result)){
                        $arrproblem[] = $value->problem_result;
                    }
                    // Check Root cause Column
                    if(strlen($value->rootcause)){
                        $arrrootcause[] = $value->rootcause;
                    }
                    if(strlen($value->rootcause_result)){
                        $arrrootcause[] = $value->rootcause_result;
                    }
                    //Check action Column
                    if(strlen($value->action)){
                        $arraction[] = $value->action;
                    }
                    if(strlen($value->action_result)){
                        $arraction[] = $value->action_result;
                    }

                    $sheet->setCellValue('A'.$row, $set->name_tester );
                    $sheet->setCellValue('B'.$row, $value->due_date );
                    $sheet->setCellValue('C'.$row, $value->recoredtime );
                    $sheet->setCellValue('D'.$row, $value->operation );

                    if($value->recoredtime == null){
                        $sheet->setCellValue('E'.$row, 'On Going' );
                    }else{
                        if($value->recoredtime > $value->due_date){ // ส่งล่าช้า
                            $sheet->setCellValue('E'.$row, 'DONE (Delay)' );
                        }else{
                            $sheet->setCellValue('E'.$row, 'DONE' );
                        }
                    }

                    if($value->results == "PASS"){
                        $sheet->setCellValue('F'.$row, 'PASS' );
                    }elseif ($value->results == "NOT_PASS") {
                        $sheet->setCellValue('F'.$row, 'NOT PASS' );
                    }else{ // DONOTUSE
                        $sheet->setCellValue('F'.$row, "DON'T USE" );
                    }

                    $sheet->setCellValue('G'.$row, implode("|", $arrproblem) );
                    $sheet->setCellValue('H'.$row, implode("|", $arrrootcause) );
                    $sheet->setCellValue('I'.$row,implode("|", $arraction) );

                    // Results => PASS
                    if($value->results == "PASS"){
                        $sheet->getStyle('F'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('2ed878');
                    }

                    // Results => NOT PASS
                    if($value->results == "NOT_PASS"){
                        $sheet->getStyle('F'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('ff5370');
                    }

                    // Results => DON'T USE
                    if($value->results == "DONOTUSE"){
                        $sheet->getStyle('F'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('959595');
                    }


                    // Status
                    if($value->recoredtime == null){
                        $sheet->getStyle('E'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('FFB64D');
                    }else{
                        if($value->recoredtime > $value->due_date){ // ส่งล่าช้า
                            $sheet->getStyle('E'.$row)->getFill()
                            ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                            ->getStartColor()->setARGB('73b4ff');
                        }else{
                            $sheet->getStyle('E'.$row)->getFill()
                            ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                            ->getStartColor()->setARGB('2ed878');
                        }
                    }

                    $sheet->getStyle('E'.$row)->applyFromArray(
                        [
                            'font' => [
                                'color' => [
                                    'rgb' => 'ffffff'
                                ]
                            ]
                        ]
                    );
                    $sheet->getStyle('F'.$row)->applyFromArray(
                        [
                            'font' => [
                                'color' => [
                                    'rgb' => 'ffffff'
                                ]
                            ]
                        ]
                    );

                    $sheet->getRowDimension($row)->setRowHeight(34);

                    $row++;
                }   



            })->setFilename($namefile)->store('xlsx', storage_path('NHK-File/report/dailycheck'));

            return response()->json(['success' =>  1,'filename' => $namefile.'.xlsx']);


        }

        public function monitoring_export(Request $request)
        {
            
            if(empty($request->start_date) && empty($request->end_date))
            {
                $start = date('Y-m-1');
                $end = date('Y-m-t');
    
                $data = DB::table('nt_monitor_set')
                ->join('nt_monitor_info', 'nt_monitor_info.id_mns', '=', 'nt_monitor_set.id_mns')
                ->join('nt_monitor_unit', 'nt_monitor_unit.id_mnu', '=', 'nt_monitor_set.id_mnu')
                ->whereBetween('nt_monitor_info.due_date', [$start, $end])
                ->orderby('nt_monitor_info.due_date','ASC')
                ->get();
    
            }else{
    
                $start = date('Y-m-d', strtotime($request->start_date));
                $end = date('Y-m-d', strtotime($request->end_date. "+1 days"));
    
                $data = DB::table('nt_monitor_set')
                ->join('nt_monitor_info', 'nt_monitor_info.id_mns', '=', 'nt_monitor_set.id_mns')
                ->join('nt_monitor_unit', 'nt_monitor_unit.id_mnu', '=', 'nt_monitor_set.id_mnu')
                ->whereBetween('nt_monitor_info.due_date', [$start, $end])
                ->orderby('nt_monitor_info.due_date','ASC')
                ->get();
    
            }

            $namefile = "excel_monitoring_".date('YmdHis');
            $file = storage_path('NHK-File/template/report/template_monitoring.xlsx');

            Excel::load($file, function($doc)use($data) {

                $sheet = $doc->setActiveSheetIndex(0);

