                    $sheet->setCellValue('A'.$row, $value->name_tester );
                    $sheet->setCellValue('B'.$row, $value->topic );
                    $sheet->setCellValue('C'.$row, $value->due_date );
                    $sheet->setCellValue('D'.$row, $value->recoredtime );
                    $sheet->setCellValue('E'.$row, $value->operation );

                    if($value->recoredtime == null){
                        $sheet->setCellValue('F'.$row, 'On Going' );
                    }else{
                        if($value->recoredtime > $value->due_date){ // ส่งล่าช้า
                            $sheet->setCellValue('F'.$row, 'DONE (Delay)' );
                        }else{
                            $sheet->setCellValue('F'.$row, 'DONE' );
                        }
                    }

                    if($value->results == "PASS"){
                        $sheet->setCellValue('G'.$row, 'PASS' );
                    }elseif ($value->results == "NOT_PASS") {
                        $sheet->setCellValue('G'.$row, 'NOT PASS' );
                    }else{ // DONOTUSE
                        $sheet->setCellValue('G'.$row, "DON'T USE" );
                    }

                    $sheet->setCellValue('H'.$row, implode(" | ", $arrproblem) );
                    $sheet->setCellValue('I'.$row, implode(" | ", $arrrootcause) );
                    $sheet->setCellValue('J'.$row,implode(" | ", $arraction) );

                    // Results => PASS
                    if($value->results == "PASS"){
                        $sheet->getStyle('G'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('2ed878');
                    }

                    // Results => NOT PASS
                    if($value->results == "NOT_PASS"){
                        $sheet->getStyle('G'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('ff5370');
                    }

                    // Results => DON'T USE
                    if($value->results == "DONOTUSE"){
                        $sheet->getStyle('G'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('959595');
                    }


                    // Status
                    if($value->recoredtime == null){
                        $sheet->getStyle('F'.$row)->getFill()
                        ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                        ->getStartColor()->setARGB('FFB64D');
                    }else{
                        if($value->recoredtime > $value->due_date){ // ส่งล่าช้า
                            $sheet->getStyle('F'.$row)->getFill()
                            ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                            ->getStartColor()->setARGB('73b4ff');
                        }else{
                            $sheet->getStyle('F'.$row)->getFill()
                            ->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)
                            ->getStartColor()->setARGB('2ed878');
                        }
                    }

                    $sheet->getStyle('F'.$row)->applyFromArray(
                        [
                            'font' => [
                                'color' => [
                                    'rgb' => 'ffffff'
                                ]
                            ]
                        ]
                    );
                    $sheet->getStyle('G'.$row)->applyFromArray(
                        [
                            'font' => [
                                'color' => [
                                    'rgb' => 'ffffff'
                                ]
                            ]
                        ]
                    );

                    $sheet->getRowDimension($row)->setRowHeight(34);

                    $row++;
                }   



            })->setFilename($namefile)->store('xlsx', storage_path('NHK-File/report/monitoring'));

            return response()->json(['success' =>  1,'filename' => $namefile.'.xlsx']);
            
        }

        
