    //New
     public function reporttgadate()
    {

        try {
            
            $spreadsheet = new Spreadsheet();
            $sheet = $spreadsheet->getActiveSheet();
            $sheet->setTitle('TGA');

            $tgadate = DB::table('nt_oqa_lab')
            ->select('nt_model.name_model','nt_oqa_lab.id_createlab','nt_oqa_lab.lotnumber_lab','nt_oqa_lab.tga','nt_oqa_lab.save_date')
            ->join('nt_model', 'nt_oqa_lab.id_model', '=', 'nt_model.id_model')->get();

            $sheet->setCellValue('A1', 'Modal');
            $sheet->setCellValue('B1', 'Log Number');
            $sheet->setCellValue('C1', 'TGA date code (Produced)');
            $sheet->setCellValue('D1', 'Start time (Received)');
            $sheet->setCellValue('E1', 'id key');
            
            $sheet->getStyle('A1:D1')->getFont()->setBold(true);

            $row = 2;
              foreach ($tgadate as $item) {
                $sheet->setCellValue('A' . $row, $item->name_model);
                $sheet->setCellValue('B' . $row, $item->lotnumber_lab);
                $sheet->setCellValue('C' . $row, ($item->tga ? date('d-M-Y',strtotime($item->tga)) : null) );
                $sheet->setCellValue('D' . $row, date('d-M-Y',strtotime($item->save_date)));
                $sheet->setCellValue('E' . $row, $item->id_createlab);
                $row++;
            }

            $sheet->getColumnDimension('A')->setWidth(25);
            $sheet->getColumnDimension('B')->setWidth(30);
            $sheet->getColumnDimension('C')->setWidth(17);
            $sheet->getColumnDimension('D')->setWidth(17);
            $sheet->getColumnDimension('E')->setWidth(17);

            $fileType='Xlsx';
            $namefile = 'TGADateCode_'.date("YmdHis").'.Xlsx';
            $writer = IOFactory::createWriter($spreadsheet, $fileType);
            $writer->setIncludeCharts(true); 
            ob_end_clean();
            $writer->save('local/storage/NHK-File/TGA/'.$namefile);

            return response()->json(['success' => 1 ,'filename' => $namefile]);

        } catch (\Exception $e) {
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }
    //New
    public function upload_tga(Request $request)
    {

         $request->validate([
            'excel_file' => 'required|mimes:xlsx,xls'
        ]);

        try {
            $file = $request->file('excel_file');
            $spreadsheet = IOFactory::load($file->getRealPath());
            $sheet = $spreadsheet->getActiveSheet();
            
            $data = [];
            $highestRow = $sheet->getHighestRow();
            for ($rowNumber = 2; $rowNumber <= $highestRow; $rowNumber++) {
                $dateCell = $sheet->getCell('C' . $rowNumber);
                $rawValue = $dateCell->getValue();
                
                $id = $sheet->getCell('E' . $rowNumber)->getValue();

                $finalDateValue = null;

                if (!empty($rawValue)) {
                    if (is_numeric($rawValue)) {
                        $dateTimeObject = Date::excelToDateTimeObject($rawValue);
                        $finalDateValue = $dateTimeObject->format('Y-m-d');
                    } else {
                        $finalDateValue = $dateCell->getFormattedValue();
                    }
                }
                
                $datasave = [
                    'tga' => $finalDateValue
                ];

                // $data[] = [
                //     'id' => $id
                // ];
                if(DB::table('nt_oqa_lab')->where('id_createlab',$id)->count() > 0){
                    $existingRecord  = DB::table('nt_oqa_lab')->where('id_createlab',$id)->update($datasave);
                    // ตรวจสอบว่ามีข้อมูลอยู่จริงหรือไม่
                    if (!$existingRecord) {

                        $messages = 'Update Failed';
                        return response()->json(['success' => 2, 'messages' => $messages]);

                    }else {
                        try {
                            return response()->json(['success' =>  1]);

                        } catch (QueryException $e) {

                            $messages = 'Update Failed: ' . $existingRecord->lotnumber_lab;
                            return response()->json(['success' => 2, 'messages' => $messages]);

                        }
                    }
                }else{
                    $messages = 'Update Failed';
                    return response()->json(['success' => 2, 'messages' => $messages]);
                } 

            }

        } catch (\Exception $e) {
            return response()->json(['success' =>  2, 'error' => $e->getMessage()]);
            // return response()->json([
            //     'success' => false,
            //     'error' => $e->getMessage()
            // ], 500);
        }
        
    }




